import Foundation

/// A logistic regression over the detector's signals for one word and one re-reading, trained
/// offline (post-MVP 04, `Tests/EngineTests/DetectorModelExperiment.swift`). Its weights live in
/// `DetectorModelWeights.swift`, generated by that training.
public struct DetectorModel: Sendable {
    public let weights: [Double]
    public let bias: Double
    public let mean: [Double]
    public let scale: [Double]
    /// Re-readings at or above this probability are corrected.
    public let threshold: Double

    public init(weights: [Double], bias: Double, mean: [Double], scale: [Double], threshold: Double) {
        self.weights = weights
        self.bias = bias
        self.mean = mean
        self.scale = scale
        self.threshold = threshold
    }

    /// The model's input, in training and in the Engine alike.
    public static func features(
        typedTrigram: Double, rereadTrigram: Double, typedFrequency: Double?, rereadFrequency: Double?,
        keyCount: Int, rereadNonLetters: Int
    ) -> [Double] {
        [
            typedTrigram, rereadTrigram, rereadTrigram - typedTrigram,
            typedFrequency ?? 0, typedFrequency == nil ? 0 : 1, rereadFrequency ?? 0, rereadFrequency == nil ? 0 : 1,
            log(Double(keyCount)), Double(rereadNonLetters),
        ]
    }

    public func probability(_ features: [Double]) -> Double {
        var z = bias
        for i in features.indices { z += weights[i] * (features[i] - mean[i]) / scale[i] }
        return 1 / (1 + exp(-z))
    }
}
